import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Apps & Modules","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app.md","filePath":"guide/app.md","lastUpdated":1793025209000}'),t={name:"guide/app.md"};function l(p,s,c,r,d,i){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="apps-modules" tabindex="-1">Apps &amp; Modules <a class="header-anchor" href="#apps-modules" aria-label="Permalink to &quot;Apps &amp; Modules&quot;">​</a></h1><p>An agent repository is one entry file: <code>export default createApp({ agents, modules })</code>. <a href="/reference/app"><code>@chamvi/app</code></a> boots config, store, engine, channels and HTTP from environment variables and shuts them down in order; <a href="/reference/cli"><code>@chamvi/cli</code></a> turns that into a process with <code>chamvi dev | build | start | run-job | migrate</code>, signals and exit codes.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/app</span><span style="color:#E7C58C;"> @chamvi/cli</span><span style="color:#E7C58C;"> ai</span><span style="color:#E7C58C;"> @ai-sdk/anthropic</span><span style="color:#E7C58C;"> typeorm</span><span style="color:#E7C58C;"> pg</span></span>
<span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> --save-dev</span><span style="color:#E7C58C;"> tsdown</span><span style="color:#958A8B;">   # only for chamvi build</span></span></code></pre></div><p><code>@chamvi/app</code> is a library without process concerns: it registers no signal handlers, never calls <code>process.exit</code> and reads no argv. Everything about the process lives in the CLI.</p><h2 id="the-entry" tabindex="-1">The entry <a class="header-anchor" href="#the-entry" aria-label="Permalink to &quot;The entry&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// src/index.ts</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    consoleChannelModule,</span></span>
<span class="line"><span style="color:#E6DFDE;">    createApp,</span></span>
<span class="line"><span style="color:#E6DFDE;">    cron,</span></span>
<span class="line"><span style="color:#E6DFDE;">    defineAgent,</span></span>
<span class="line"><span style="color:#E6DFDE;">    http,</span></span>
<span class="line"><span style="color:#E6DFDE;">} </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> digest = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // resolved through @ai-sdk/anthropic and ANTHROPIC_API_KEY, never the Vercel Gateway</span></span>
<span class="line"><span style="color:#E6DFDE;">    model: </span><span style="color:#E7C58C;">&#39;anthropic/claude-sonnet-5-5&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Summarize what happened since the last digest.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [</span></span>
<span class="line"><span style="color:#958A8B;">        // POST /agents/digest/runs, the dashboard and MCP</span></span>
<span class="line"><span style="color:#E6DFDE;">        http.on(),</span></span>
<span class="line"><span style="color:#958A8B;">        // weekdays at 08:00, Berlin time</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron.on(</span><span style="color:#E7C58C;">&#39;0 8 * * 1-5&#39;</span><span style="color:#E6DFDE;">, { timezone: </span><span style="color:#E7C58C;">&#39;Europe/Berlin&#39;</span><span style="color:#E6DFDE;"> }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// synchronous and side-effect free: chamvi start | run-job | migrate load this default export</span></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> default</span><span style="color:#E6DFDE;"> createApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [digest],</span></span>
<span class="line"><span style="color:#958A8B;">    // tools write to it with ctx.channels.findOneOrFail(&#39;console&#39;).emit(...)</span></span>
<span class="line"><span style="color:#E6DFDE;">    modules: [consoleChannelModule()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><ul><li>The entry is <code>src/index.ts</code>. <code>dev</code>, <code>build</code> and <code>start --dev</code> take <code>--entry</code>, else the <code>package.json</code> field <code>&quot;chamvi&quot;: { &quot;entry&quot;: &quot;&lt;path&gt;&quot; }</code>, else <code>src/index.ts</code>. The built commands (<code>start</code>, <code>run-job</code>, <code>migrate</code>) default to <code>dist/index.mjs</code> and never read that field. Without any entry file the commands run the default app, <code>createApp({})</code>, whose agents come from <code>./agents</code>: a folder of <a href="/guide/agent-folders">agent folders</a> is a complete app.</li><li><code>createApp()</code> is synchronous and side-effect free: no env read, no I/O, no provider import. Everything happens in <code>start()</code>, <code>runJob()</code> and <code>migrate()</code>, which the CLI calls.</li><li>An entry whose default export is not an app (checked with <code>isApp()</code>, which also recognizes an app of another installed copy) makes the CLI exit 2.</li><li><code>@chamvi/app</code> re-exports <code>@chamvi/core</code> and the common part of <code>@chamvi/http</code> (<code>agentPermission</code>, <code>Permission</code> and the <code>Authenticator</code>, <code>Principal</code>, <code>HttpRoute*</code>, <code>StaticToken</code> types), so an agent repository imports one package.</li></ul><p><code>dev</code> runs the source through Node&#39;s type stripping and <code>build</code> bundles it with tsdown, so the code has to suit both: relative imports carry <code>.ts</code> and there is no <code>enum</code>. The template <code>tsconfig.json</code>:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">{</span></span>
<span class="line"><span style="color:#E6DFDE;">    &quot;</span><span style="color:#E7C58C;">compilerOptions</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">target</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">&quot;ES2023&quot;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">module</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">&quot;NodeNext&quot;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">moduleResolution</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">&quot;NodeNext&quot;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">strict</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">skipLibCheck</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">verbatimModuleSyntax</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">allowImportingTsExtensions</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">erasableSyntaxOnly</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        &quot;</span><span style="color:#E7C58C;">noEmit</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: </span><span style="color:#FF7B84;">true</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">    &quot;</span><span style="color:#E7C58C;">include</span><span style="color:#E6DFDE;">&quot;</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;src&quot;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&quot;test&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><h2 id="model-strings" tabindex="-1">Model strings <a class="header-anchor" href="#model-strings" aria-label="Permalink to &quot;Model strings&quot;">​</a></h2><p>An agent&#39;s <code>model</code> may be a string <code>&#39;&lt;provider&gt;/&lt;model&gt;&#39;</code>, the AI SDK&#39;s own form (<code>&#39;openai/gpt-5&#39;</code>); the provider is the part before the first <code>/</code>, so a model id may hold one (<code>&#39;openrouter/meta-llama/llama-3.1&#39;</code>). It resolves through an AI SDK provider registry of every installed provider package (<code>@ai-sdk/anthropic</code>, <code>@ai-sdk/openai</code>, <code>@ai-sdk/google</code>, <code>@ai-sdk/mistral</code>, <code>@ai-sdk/xai</code>) with its key from env (<code>ANTHROPIC_API_KEY</code>, ...), overridden per provider by <code>createApp({ models })</code>. <code>start</code> and <code>runJob</code> check every string model first: a provider package that is not installed or a key that is not set throws <code>InvalidAgentDefinitionError</code> naming the package or the variable, and the CLI exits 2. A string never reaches the Vercel Gateway. A <code>LanguageModel</code> object is used as is.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><p>Modules are <a href="https://github.com/tada5hi/orkos" target="_blank" rel="noreferrer">orkos</a> <code>IModule</code>s on an <a href="https://github.com/tada5hi/eldin" target="_blank" rel="noreferrer">eldin</a> container, unwrapped. Seven built-in modules are always there; listing a module with a built-in&#39;s name (<code>ModuleName</code>) replaces it, which is also how you configure one (<code>storeModule({ dataSource })</code>, <code>httpModule({ cors })</code>). Two modules of one name, a built-in&#39;s included, throw <code>InvalidAgentDefinitionError</code> from <code>createApp</code>.</p><table tabindex="0"><thead><tr><th>Module</th><th>Does</th></tr></thead><tbody><tr><td><code>configModule()</code></td><td>Reads every variable once (<a href="/reference/app#environment">environment</a>) and registers the config, the clock and the JSON line logger</td></tr><tr><td><code>storeModule()</code></td><td>A <code>TypeormStore</code> over <code>DATABASE_URL</code>, migrated unless <code>CHAMVI_MIGRATE=false</code>, plus the hourly <code>purgeExpired()</code>; without <code>DATABASE_URL</code> a <code>MemoryStore</code> (warned outside dev)</td></tr><tr><td><code>staticTokensModule()</code></td><td>The <code>staticTokens()</code> authenticator from <code>CHAMVI_TOKENS</code></td></tr><tr><td><code>engineModule()</code></td><td>Checks the model strings, builds the <code>Engine</code> with every contributed channel (<code>AppToken.CHANNELS</code>) and starts it, which starts the channels</td></tr><tr><td><code>agentsModule()</code></td><td>Loads the <a href="/guide/agent-folders">agent folders</a> of <code>CHAMVI_AGENTS_DIR</code> (else <code>./agents</code> when it exists) before the engine starts and watches them; an app with no agent at all starts with a warning</td></tr><tr><td><code>schedulerModule()</code></td><td>The <code>cron</code> channel (<code>cronChannel()</code> from <code>@chamvi/channel-cron</code>); <code>CHAMVI_SCHEDULER=false</code> leaves firing to Kubernetes CronJobs and <code>chamvi run-job</code> (<code>cron.on()</code> subscriptions still validate)</td></tr><tr><td><code>httpModule()</code></td><td>The <code>http</code>, <code>mcp</code> and <code>webhook</code> channels, <code>createHttpApp()</code> with every contributed route and authenticator, mounting every contributed channel with an <code>in</code> at <code>/channels/&lt;name&gt;</code>, the graceful shutdown, <code>serve()</code> on <code>HOST</code>:<code>PORT</code></td></tr></tbody></table><p>The optional modules ship with the package they configure, on its <code>/module</code> subpath (<code>@chamvi/app</code> is an optional peer there, and the package&#39;s main entry never imports it), so install the feature package of each one you use. Each factory reads its variables <strong>when it is called</strong>, that is when the entry is imported, and exposes its instance at once (<code>.app</code>, <code>.manager</code>). Each module also <strong>provides its instance on the engine</strong> before it starts, so a tools factory injects it per execution with the package&#39;s <code>inject*Context(ctx)</code> (see <a href="/guide/tools#context-shared-instances-for-tools">Context</a>); a channel a module contributes is reached with <code>ctx.channels.findOne(name)</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// src/index.ts</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">    ToolDeniedError,</span></span>
<span class="line"><span style="color:#E6DFDE;">    createApp,</span></span>
<span class="line"><span style="color:#E6DFDE;">    defineAgent,</span></span>
<span class="line"><span style="color:#E6DFDE;">} </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { githubModule } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/github/module&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { openclawModule } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/channel-openclaw/module&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { sandboxModule } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/sandbox/module&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { uiModule } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/ui/module&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { codingTools } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/coding&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { github, injectGithubContext } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/github&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { injectSandboxContext } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/sandbox&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// every factory reads its env when it is called (GITHUB_APP_ID, GITHUB_APP_PRIVATE_KEY, ...)</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> githubApp = githubModule();</span></span>
<span class="line"><span style="color:#958A8B;">// CHAMVI_SANDBOX_PROVIDER, when set, wins over the option</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> sandbox = sandboxModule({</span></span>
<span class="line"><span style="color:#E6DFDE;">    provider: </span><span style="color:#E7C58C;">&#39;docker&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    allowRepo: (url) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> url.startsWith(</span><span style="color:#E7C58C;">&#39;https://github.com/acme/&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> repro = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;repro&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model: </span><span style="color:#E7C58C;">&#39;anthropic/claude-sonnet-5-5&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Reproduce the reported bug with a failing test and comment the result.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [github.on(</span><span style="color:#E7C58C;">&#39;issues.labeled&#39;</span><span style="color:#E6DFDE;">)],</span></span>
<span class="line"><span style="color:#958A8B;">    // each module provides its instance on the engine; a factory injects it per execution</span></span>
<span class="line"><span style="color:#958A8B;">    // (github.app and sandbox.manager still exist at import time, for definition-time use)</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: (ctx) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> manager = injectSandboxContext(ctx);</span></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">            ...injectGithubContext(ctx).readTools(),</span></span>
<span class="line"><span style="color:#E6DFDE;">            ...manager.tools(),</span></span>
<span class="line"><span style="color:#E6DFDE;">            ...codingTools(manager),</span></span>
<span class="line"><span style="color:#E6DFDE;">        };</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">    hooks: {</span></span>
<span class="line"><span style="color:#958A8B;">        // every shell command waits for the owner, asked in their OpenClaw chat</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> beforeToolExecution({ toolName, input }, ctx) {</span></span>
<span class="line"><span style="color:#FF7B84;">            if</span><span style="color:#E6DFDE;"> (toolName !== </span><span style="color:#E7C58C;">&#39;bash&#39;</span><span style="color:#E6DFDE;">) </span><span style="color:#FF7B84;">return</span><span style="color:#E6DFDE;"> input;</span></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> { approved } = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> ctx.channels.findOneOrFail(</span><span style="color:#E7C58C;">&#39;openclaw&#39;</span><span style="color:#E6DFDE;">).approve({</span></span>
<span class="line"><span style="color:#E6DFDE;">                title: </span><span style="color:#E7C58C;">&#39;Run a shell command?&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                body: (input </span><span style="color:#FF7B84;">as</span><span style="color:#E6DFDE;"> { command: string }).command,</span></span>
<span class="line"><span style="color:#E6DFDE;">            });</span></span>
<span class="line"><span style="color:#FF7B84;">            if</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">approved) </span><span style="color:#FF7B84;">throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> ToolDeniedError(</span><span style="color:#E7C58C;">&#39;The owner refused the command.&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E6DFDE;"> input;</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> default</span><span style="color:#E6DFDE;"> createApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [repro],</span></span>
<span class="line"><span style="color:#E6DFDE;">    modules: [</span></span>
<span class="line"><span style="color:#958A8B;">        // the github channel: deliveries at POST /channels/github, comments out</span></span>
<span class="line"><span style="color:#E6DFDE;">        githubApp,</span></span>
<span class="line"><span style="color:#958A8B;">        // attached to the engine on start, closed after the engine drained</span></span>
<span class="line"><span style="color:#E6DFDE;">        sandbox,</span></span>
<span class="line"><span style="color:#958A8B;">        // the channel named &#39;openclaw&#39;, approval links from CHAMVI_PUBLIC_URL</span></span>
<span class="line"><span style="color:#E6DFDE;">        openclawModule(),</span></span>
<span class="line"><span style="color:#958A8B;">        // the dashboard at /ui</span></span>
<span class="line"><span style="color:#E6DFDE;">        uiModule(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Factory</th><th>Entry</th><th>Contributes</th><th>Context</th></tr></thead><tbody><tr><td><code>githubModule()</code></td><td><code>@chamvi/github/module</code></td><td><code>.app</code> (<code>IGithubApp</code>), the <code>github</code> channel: signed deliveries at <code>/channels/github</code>, comments out</td><td><code>injectGithubContext(ctx)</code>, <code>ctx.channels.findOne(&#39;github&#39;)</code></td></tr><tr><td><code>sandboxModule()</code></td><td><code>@chamvi/sandbox/module</code></td><td><code>.manager</code> (<code>IWorkspaceManager</code>), attached on start, closed after the engine drained</td><td><code>injectSandboxContext(ctx)</code></td></tr><tr><td><code>openclawModule()</code></td><td><code>@chamvi/channel-openclaw/module</code></td><td>the <code>openclawChannel()</code> named <code>openclaw</code> (out only)</td><td><code>ctx.channels.findOne(&#39;openclaw&#39;)</code></td></tr><tr><td><code>uiModule()</code></td><td><code>@chamvi/ui/module</code></td><td>the <a href="/guide/ui">dashboard</a> at <code>&lt;basePath&gt;/ui</code></td><td></td></tr><tr><td><code>authupModule()</code>, <code>oidcModule(options)</code></td><td><code>@chamvi/app/authup</code></td><td>the <code>authup()</code> and <code>oidc()</code> authenticators, after the static tokens</td><td></td></tr><tr><td><code>consoleChannelModule({ name?, write? })</code></td><td><code>@chamvi/app</code></td><td>the <code>consoleChannel()</code> named <code>console</code> (out only)</td><td><code>ctx.channels.findOne(&#39;console&#39;)</code></td></tr></tbody></table><p>Channel names are unique per app, so <code>openclawModule()</code> beside <code>openclawModule({ name: &#39;ops&#39; })</code> contributes two channels (<code>ctx.channels.findOne(&#39;ops&#39;)</code>); two channels of one name fail the setup with <code>InvalidAgentDefinitionError</code>. <code>@chamvi/app/authup</code> stays in the app package, since <code>@chamvi/http</code> cannot depend on <code>@chamvi/app</code>.</p><p>With <code>CHAMVI_PUBLIC_URL</code> set, the GitHub and OpenClaw modules link approvals to the dashboard: <code>&lt;CHAMVI_PUBLIC_URL&gt;&lt;basePath&gt;/ui/approvals?run=&lt;runId&gt;&amp;approval=&lt;approvalId&gt;</code>, without a token. A factory missing a required variable throws <code>InvalidAgentDefinitionError</code> naming it; no message ever echoes a value.</p><h2 id="setup-contributes-onready-consumes" tabindex="-1">Setup contributes, onReady consumes <a class="header-anchor" href="#setup-contributes-onready-consumes" aria-label="Permalink to &quot;Setup contributes, onReady consumes&quot;">​</a></h2><p>orkos sets every module up in dependency order, then calls every <code>onReady</code>. chamvi splits the work along that line:</p><ul><li>In <strong><code>setup</code></strong>, a module registers what it contributes on the container&#39;s collection tokens: <code>AppToken.HTTP_ROUTES</code>, <code>CHANNELS</code>, <code>AUTHENTICATORS</code> (with an <code>order</code>, lowest first), <code>LIFECYCLE_HOOKS</code> and <code>AGENT_CHECKS</code> (an <code>(agent) =&gt; void</code> that throws <code>InvalidAgentDefinitionError</code> for a folder agent the module could not serve, run before the agent is registered).</li><li>In <strong><code>onReady</code></strong>, the consumers build: the engine module collects the channels, the http module the routes, the authenticators and the channels it mounts.</li></ul><p>So a contribution never depends on module order. A module that resolves <code>ENGINE</code> or <code>SERVER</code> in its own <code>onReady</code> lists that module in <code>dependencies</code>. Nothing starts in <code>onReady</code>: the engine and the http module register start steps, which the app runs (the engine with its channels, then the <code>started</code> hooks and listening) only once every module&#39;s <code>onReady</code> ran, user modules included. So a configuration error any of them finds starts nothing: no queued run of the shared store executes on a replica that then exits 2.</p><h2 id="start-and-stop" tabindex="-1">Start and stop <a class="header-anchor" href="#start-and-stop" aria-label="Permalink to &quot;Start and stop&quot;">​</a></h2><p><code>app.start()</code> resolves once the server listens, so <code>/readyz</code> turns green only after everything runs:</p><ol><li>config</li><li>store (and the migrations, advisory-locked, so every replica may run them)</li><li>every <code>onReady</code>: the engine is built with every contributed channel, the <a href="/guide/agent-folders">agent folders</a> are loaded into it, the HTTP app is built, nothing runs yet</li><li><code>engine.start()</code>: recovery, then every channel&#39;s <code>start()</code> (the cron schedule among them)</li><li>the purge timer and the agents dir watcher</li><li><code>serve()</code> on <code>HOST</code>:<code>PORT</code>, listening last</li></ol><p><code>app.stop()</code> is memoized and also stops a start still setting up (which then never listens):</p><ol><li><code>/readyz</code> answers 503, then <code>CHAMVI_READINESS_DELAY_MS</code> (0)</li><li>the <code>stopping</code> hooks: the purge timer and the agents dir watcher stop</li><li>the app&#39;s closers (SSE streams, MCP waits)</li><li><code>server.close()</code></li><li><code>engine.drain()</code>: every channel&#39;s <code>stop()</code> first, then up to <code>CHAMVI_DRAIN_TIMEOUT_MS</code> (30 s) for the runs</li><li>up to <code>CHAMVI_CLOSE_TIMEOUT_MS</code> (5 s) for the close, then <code>server.close(true)</code></li><li>the workspace manager closes (with <code>sandboxModule</code>, up to 30 s)</li><li>the store&#39;s data source is destroyed</li></ol><p>orkos swallows teardown errors; chamvi does not: every teardown error is logged, and <code>stop()</code> then rejects with <code>app_stop_failed</code> (the CLI exits 1). An app runs one lifecycle: a second <code>start()</code>, <code>runJob()</code> or <code>migrate()</code> rejects with <code>app_in_use</code>.</p><p><code>runJob({ agent, subscription? })</code> builds config, store and engine (with the folder agents, loaded once), starts no channel and no HTTP, fires the cron subscription once through <a href="/guide/scheduler"><code>runJob()</code></a> and tears down. <code>migrate()</code> only migrates the store; it fails without <code>DATABASE_URL</code>.</p><h2 id="writing-a-module" tabindex="-1">Writing a module <a class="header-anchor" href="#writing-a-module" aria-label="Permalink to &quot;Writing a module&quot;">​</a></h2><p>The module contract comes from the main entry of <code>@chamvi/app</code>: <code>AppToken</code>, <code>ModuleName</code>, <code>AppContext</code>, <code>ILifecycleHook</code>, the env readers and the orkos <code>IModule</code> and eldin <code>IContainer</code> types, so a module needs no direct orkos or eldin import. A module that shares an instance with tools provides it in the <code>engineCreated</code> hook and exports an <code>inject*</code> function next to it, keeping its key internal:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> interface</span><span style="color:#E6DFDE;"> IAuditLog {</span></span>
<span class="line"><span style="color:#E6DFDE;">    write(line: string): void;</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// the key stays inside the package; the pair below is its public face</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> AUDIT_CONTEXT = defineContextKey&lt;IAuditLog&gt;(</span><span style="color:#E7C58C;">&#39;audit&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> function</span><span style="color:#E6DFDE;"> injectAuditContext&lt;S </span><span style="color:#FF7B84;">extends</span><span style="color:#E6DFDE;"> StateSchema = StateSchema&gt;(ctx: ToolContext&lt;S&gt;): IAuditLog {</span></span>
<span class="line"><span style="color:#FF7B84;">    return</span><span style="color:#E6DFDE;"> inject(ctx, AUDIT_CONTEXT);</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> function</span><span style="color:#E6DFDE;"> auditModule(): IModule {</span></span>
<span class="line"><span style="color:#FF7B84;">    let</span><span style="color:#E6DFDE;"> unsubscribe: (() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> void) | undefined;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">    return</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">        name: </span><span style="color:#E7C58C;">&#39;audit&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">        // onReady resolves ENGINE, so the engine module sets up first</span></span>
<span class="line"><span style="color:#E6DFDE;">        dependencies: [ModuleName.ENGINE],</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">        // setup contributes: every consumer (engine, http) builds in onReady</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> setup(container: IContainer) {</span></span>
<span class="line"><span style="color:#E6DFDE;">            container.registerMany(AppToken.HTTP_ROUTES, {</span></span>
<span class="line"><span style="color:#E6DFDE;">                useValue: {</span></span>
<span class="line"><span style="color:#E6DFDE;">                    method: </span><span style="color:#E7C58C;">&#39;GET&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                    path: </span><span style="color:#E7C58C;">&#39;/audit&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">                    // extra routes check their own credentials</span></span>
<span class="line"><span style="color:#E6DFDE;">                    handler: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({ status: </span><span style="color:#E7C58C;">200</span><span style="color:#E6DFDE;">, body: { ok: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> } }),</span></span>
<span class="line"><span style="color:#E6DFDE;">                },</span></span>
<span class="line"><span style="color:#E6DFDE;">            });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> logger = container.resolve(AppToken.LOGGER);</span></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> log: IAuditLog = { write: (line) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> logger.info(line) };</span></span>
<span class="line"><span style="color:#E6DFDE;">            container.registerMany(AppToken.LIFECYCLE_HOOKS, {</span></span>
<span class="line"><span style="color:#E6DFDE;">                useValue: {</span></span>
<span class="line"><span style="color:#E6DFDE;">                    name: </span><span style="color:#E7C58C;">&#39;audit&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">                    // before engine.start(): tools reach the log through injectAuditContext(ctx)</span></span>
<span class="line"><span style="color:#E6DFDE;">                    engineCreated: (engine) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> engine.provide(AUDIT_CONTEXT, log),</span></span>
<span class="line"><span style="color:#E6DFDE;">                    started: () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> logger.info(</span><span style="color:#E7C58C;">&#39;audit ready&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">                    drained: () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> logger.info(</span><span style="color:#E7C58C;">&#39;audit: every run drained&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">                },</span></span>
<span class="line"><span style="color:#E6DFDE;">            });</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">        // onReady consumes: the engine exists but has not started, the server is not listening yet</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> onReady(container: IContainer) {</span></span>
<span class="line"><span style="color:#958A8B;">            // migrate builds config and store only: no ENGINE to resolve</span></span>
<span class="line"><span style="color:#FF7B84;">            if</span><span style="color:#E6DFDE;"> (container.resolve(AppToken.CONTEXT).mode === </span><span style="color:#E7C58C;">&#39;migrate&#39;</span><span style="color:#E6DFDE;">) {</span></span>
<span class="line"><span style="color:#FF7B84;">                return</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#E6DFDE;">            }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> logger = container.resolve(AppToken.LOGGER);</span></span>
<span class="line"><span style="color:#E6DFDE;">            unsubscribe = container.resolve(AppToken.ENGINE).on(</span><span style="color:#E7C58C;">&#39;run.updated&#39;</span><span style="color:#E6DFDE;">, ({ run }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">                logger.info(</span><span style="color:#E7C58C;">&#39;run updated&#39;</span><span style="color:#E6DFDE;">, { run: run.id, status: run.status });</span></span>
<span class="line"><span style="color:#E6DFDE;">            });</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">        // also called after an onReady that threw half-way</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> teardown() {</span></span>
<span class="line"><span style="color:#E6DFDE;">            unsubscribe?.();</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    };</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><ul><li><strong>Hooks</strong> (<code>LIFECYCLE_HOOKS</code>): <code>engineCreated(engine)</code> before <code>engine.start()</code> (the place for <code>engine.provide()</code>; a throwing hook, such as a second value for one key, is logged through <code>context.report()</code> and the app still starts), <code>started()</code> after <code>engine.start()</code> (channels started), before the server listens, <code>stopping()</code> first in the shutdown, before the drain stops the channels, <code>drained()</code> after the engine drained and before the store closes.</li><li><strong>Failures:</strong> orkos never tears down a module whose <code>setup</code> threw, so such a <code>setup</code> closes what it opened before rethrowing. A module whose <code>onReady</code> threw is torn down, so <code>teardown</code> tolerates state that <code>onReady</code> never built.</li><li><strong>Stopping:</strong> <code>AppToken.CONTEXT</code> holds the lifecycle&#39;s <code>signal</code>, aborted once <code>stop()</code> is called; <code>throwIfStopped(context)</code> before a long step keeps a stopped start from going on. <code>context.report(error)</code> logs an error and, during <code>stop()</code>, makes it reject.</li><li><strong>Modes:</strong> <code>AppToken.CONTEXT</code> holds the <code>mode</code>: <code>start</code> builds everything, <code>job</code> (<code>runJob</code>) config, store and engine, <code>migrate</code> only config and store. A module that resolves <code>ENGINE</code> in <code>onReady</code> returns early in <code>migrate</code> mode, as the sample does, or <code>chamvi migrate</code> fails.</li><li><strong>Testing:</strong> <code>createModuleHarness({ modules, env?, agents?, clock? })</code> from <code>@chamvi/app/testing</code> runs the real module lifecycle (setup, <code>onReady</code>, the start steps) of the modules you list, built-ins included, without <code>start()</code> and a port: <code>harness.container</code> resolves what a module contributed, <code>harness.reported</code> holds every <code>context.report()</code> call, <code>harness.stop()</code> tears down. The feature packages test their own modules with it.</li><li><strong>Dependencies:</strong> <code>dependencies</code> name modules the app registers (<code>{ name, optional: true }</code> for one it may lack). A missing one, a cycle or a version mismatch throws <code>InvalidAgentDefinitionError</code> from <code>start</code>, <code>runJob</code> and <code>migrate</code> before any module set up (the CLI exits 2).</li></ul><h2 id="testing-an-app" tabindex="-1">Testing an app <a class="header-anchor" href="#testing-an-app" aria-label="Permalink to &quot;Testing an app&quot;">​</a></h2><p><code>start({ env })</code> takes the environment instead of <code>process.env</code> for the built-in modules, and <code>models</code> replaces a provider, so an app runs in a test without keys or network:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> app = createApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#958A8B;">    // &#39;anthropic/claude-sonnet-5-5&#39; resolves to the mock: no package, no key, no request</span></span>
<span class="line"><span style="color:#E6DFDE;">    models: { anthropic: customProvider({ languageModels: { </span><span style="color:#E7C58C;">&#39;claude-sonnet-5-5&#39;</span><span style="color:#E6DFDE;">: model } }) },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// the env replaces process.env for the built-in modules</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> app.start({</span></span>
<span class="line"><span style="color:#E6DFDE;">    env: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        PORT: </span><span style="color:#E7C58C;">&#39;3101&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        HOST: </span><span style="color:#E7C58C;">&#39;127.0.0.1&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        CHAMVI_TOKENS: JSON.stringify([{</span></span>
<span class="line"><span style="color:#E6DFDE;">            value: </span><span style="color:#E7C58C;">&#39;test-token-0123456789&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            id: </span><span style="color:#E7C58C;">&#39;test&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            permissions: [</span><span style="color:#E7C58C;">&#39;*&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#E6DFDE;">        }]),</span></span>
<span class="line"><span style="color:#E6DFDE;">        CHAMVI_LOG_LEVEL: </span><span style="color:#E7C58C;">&#39;error&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">try</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    const</span><span style="color:#E6DFDE;"> response = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> fetch(</span><span style="color:#E7C58C;">&#39;http://127.0.0.1:3101/agents&#39;</span><span style="color:#E6DFDE;">, { headers: { authorization: </span><span style="color:#E7C58C;">&#39;Bearer test-token-0123456789&#39;</span><span style="color:#E6DFDE;"> } });</span></span>
<span class="line"><span style="color:#FF7B84;">    return</span><span style="color:#FF7B84;"> await</span><span style="color:#E6DFDE;"> response.json();</span></span>
<span class="line"><span style="color:#E6DFDE;">} </span><span style="color:#FF7B84;">finally</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#958A8B;">    // drains the engine, closes the server and the store</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> app.stop();</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><p>The optional module factories read <code>options.env ?? process.env</code> when they are called, never <code>start({ env })</code>: configure them in a test through their own <code>env</code> option, for example <code>githubModule({ env: { GITHUB_APP_ID: &#39;1&#39;, ... } })</code>.</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ul><li><a href="/reference/app"><code>@chamvi/app</code> reference</a>: every factory, option, token and variable</li><li><a href="/reference/cli"><code>@chamvi/cli</code> reference</a>: commands, exit codes, signals and <code>dev</code></li><li><a href="/deployment/">Deployment</a>: the image, chart and template built on the CLI</li></ul>`,40)])])}const h=e(t,[["render",l]]);export{y as __pageData,h as default};
